package org.brightstats.desktop;

import java.util.*;
import com.google.gson.*;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import javafx.stage.Window;
import org.brightstats.data.*;
import org.brightstats.stats.*;

/** Guided factors, explicit ordered labels and explicit complete-row policy. */
final class OrdinalDialog {
    record Settings(List<String> sourceNames,List<PlsSem.Block> blocks,List<PlsSem.Edge> edges,OrdinalData.Specification specification,OrdinalSem.Options options){Settings{sourceNames=List.copyOf(sourceNames);blocks=List.copyOf(blocks);edges=List.copyOf(edges);var prepared=OrdinalSem.reflective(sourceNames,blocks,edges);var selected=Arrays.stream(prepared.columns()).mapToObj(sourceNames::get).toList();if(!selected.equals(specification.columns()))throw new IllegalArgumentException("Ordinal category declarations must follow the model's selected indicator/marker order.");Objects.requireNonNull(options);}void validateSource(List<String> names){if(names.size()<sourceNames.size()||!names.subList(0,sourceNames.size()).equals(sourceNames))throw new IllegalArgumentException("Ordinal source identities changed; reconfigure the factor/category bindings.");}}
    private final Dialog<Settings> dialog=new Dialog<>();
    private final ReflectiveModelForm model;
    private final ListView<String> variables=new ListView<>(),levels=new ListView<>();
    private final CheckBox confirmed=new CheckBox("I confirm this variable's category order"),complete=new CheckBox("Exclude incomplete rows for the selected ordinal indicators");
    private final Map<String,List<String>> orders=new LinkedHashMap<>();
    private final Map<String,Boolean> confirmations=new HashMap<>();
    private final Spinner<Integer> minimum=new Spinner<>(1,100,5),iterations=new Spinner<>(1,20000,1500);
    private final TextField confidence=new TextField("0.95");
    private final Label error=new Label();
    private final List<String> names;
    private final DataPreparation.Raw raw;
    private final DataPreparation.Settings preparation;
    private final List<DataPreparation.Column> definitions;
    private Settings result;
    private OrdinalDialog(Window owner,DataPreparation.Raw raw,DataPreparation.Settings preparation,List<DataPreparation.Column> definitions,List<PlsSem.Block> initial,List<PlsSem.Edge> edges,Settings previous){
        this.raw=raw;this.preparation=preparation;this.definitions=List.copyOf(definitions);names=definitions.stream().map(DataPreparation.Column::name).toList();if(raw.rows().size()>10000)throw new IllegalArgumentException("The ordinal workflow supports at most 10,000 source rows.");if(previous!=null){previous.validateSource(names);initial=previous.blocks();edges=previous.edges();for(int j=0;j<previous.specification().columns().size();j++){String name=previous.specification().columns().get(j);orders.put(name,previous.specification().orderedLevels().get(j));confirmations.put(name,true);}complete.setSelected(previous.specification().completeCases());minimum.getValueFactory().setValue(previous.options().minimumCategoryCount());iterations.getValueFactory().setValue(previous.options().maxIterations());confidence.setText(Double.toString(previous.options().confidence()));}
        if(initial.size()>5||initial.stream().anyMatch(b->b.measurementType()!=PlsSem.MeasurementType.REFLECTIVE))throw new IllegalArgumentException("The ordinal builder supports up to five reflective factors; formative constructs are not silently converted.");model=new ReflectiveModelForm(names,initial,edges);dialog.initOwner(owner);dialog.setTitle("Ordinal CFA / SEM");dialog.setResizable(true);dialog.getDialogPane().getButtonTypes().addAll(ButtonType.OK,ButtonType.CANCEL);variables.setPrefHeight(180);variables.setAccessibleText("Selected ordinal indicators");levels.setPrefHeight(180);levels.setAccessibleText("Declared category order from lowest to highest");levels.setCellFactory(ignore->new ListCell<>(){protected void updateItem(String value,boolean empty){super.updateItem(value,empty);setText(empty?null:value);setTooltip(empty||value==null?null:new Tooltip(value));}});
        variables.getSelectionModel().selectedItemProperty().addListener((o,a,b)->{if(b!=null)try{ensure(b);levels.getItems().setAll(orders.get(b));confirmed.setSelected(confirmations.getOrDefault(b,false));}catch(RuntimeException invalid){error.setText(invalid.getMessage());}});confirmed.selectedProperty().addListener((o,a,b)->{String selected=variables.getSelectionModel().getSelectedItem();if(selected!=null)confirmations.put(selected,b);});Button refresh=new Button("Review selected variables' category order");refresh.setOnAction(e->{try{variables.getItems().setAll(model.selectedColumns());variables.getSelectionModel().selectFirst();}catch(RuntimeException invalid){error.setText(invalid.getMessage());}});Button up=new Button("Move category up"),down=new Button("Move category down");up.setOnAction(e->move(-1));down.setOnAction(e->move(1));VBox category=new VBox(10,new Label("Lowest → highest response order. Numeric source values are proposed in numeric order; text order requires confirmation. Reordering a category resets its confirmation."),refresh,new HBox(12,new VBox(6,new Label("Indicators"),variables),new VBox(6,new Label("Ordered labels"),levels,new HBox(8,up,down))),confirmed,complete);category.getChildren().stream().filter(n->n instanceof Label).map(n->(Label)n).forEach(l->{l.setWrapText(true);l.setMaxWidth(760);});
        GridPane solver=new GridPane();solver.setHgap(10);solver.setVgap(10);solver.addRow(0,new Label("Minimum observed cases per category"),minimum);solver.addRow(1,new Label("Maximum optimizer iterations"),iterations);solver.addRow(2,new Label("Confidence level (dot decimal)"),confidence);minimum.setEditable(true);iterations.setEditable(true);minimum.setAccessibleText("Minimum observed cases per ordinal category");confidence.setAccessibleText("Ordinal confidence level");TabPane tabs=new TabPane(new Tab("Factors and paths",model),new Tab("Category order and missingness",category),new Tab("Estimation settings",solver));tabs.getTabs().forEach(t->t.setClosable(false));Label note=new Label("Polychoric DWLS with threshold-adjusted full-moment sandwich SE and a scaled/shifted test. Reflective factors use fixed unit markers and unit response residual scales. Category codes are not treated as continuous distances. All selected source rows are recovered before the explicit missing-row policy.");note.setWrapText(true);note.setMaxWidth(780);VBox content=new VBox(12,note,tabs,error);content.setStyle("-fx-padding:12;");content.setPrefWidth(820);ScrollPane scroll=new ScrollPane(content);scroll.setFitToWidth(true);scroll.setPrefViewportHeight(670);dialog.getDialogPane().setContent(scroll);error.setWrapText(true);dialog.getDialogPane().lookupButton(ButtonType.OK).addEventFilter(javafx.event.ActionEvent.ACTION,event->{result=null;try{result=read();error.setText("");}catch(RuntimeException invalid){error.setText(invalid.getMessage());event.consume();}});dialog.setResultConverter(button->button==ButtonType.OK?result:null);if(!model.selectedColumns().isEmpty()){variables.getItems().setAll(model.selectedColumns());variables.getSelectionModel().selectFirst();}
    }
    private void ensure(String name){if(orders.containsKey(name))return;int index=names.indexOf(name);orders.put(name,OrdinalData.observedLevels(raw,preparation,definitions,index));confirmations.put(name,definitions.get(index).kind()==DataPreparation.Kind.NUMERIC);}
    private void move(int direction){int i=levels.getSelectionModel().getSelectedIndex();if(i<0||i+direction<0||i+direction>=levels.getItems().size())return;Collections.swap(levels.getItems(),i,i+direction);levels.getSelectionModel().select(i+direction);String selected=variables.getSelectionModel().getSelectedItem();orders.put(selected,List.copyOf(levels.getItems()));confirmed.setSelected(false);}
    private Settings read(){var blocks=model.blocks();var edges=model.edges();var prepared=OrdinalSem.reflective(names,blocks,edges);List<String> selected=Arrays.stream(prepared.columns()).mapToObj(names::get).toList();List<List<String>> declared=new ArrayList<>();for(String name:selected){ensure(name);if(!confirmations.getOrDefault(name,false))throw new IllegalArgumentException("Confirm the ordered levels for "+name+" in the category-order tab.");declared.add(orders.get(name));}var spec=new OrdinalData.Specification(selected,declared,complete.isSelected());OrdinalData.prepare(raw,preparation,definitions,spec);return new Settings(names,blocks,edges,spec,new OrdinalSem.Options(Integer.parseInt(iterations.getEditor().getText().strip()),1e-8,1e-12,Double.parseDouble(confidence.getText().strip()),Integer.parseInt(minimum.getEditor().getText().strip())));}
    static Optional<Settings> show(Window owner,DataPreparation.Raw raw,DataPreparation.Settings preparation,List<DataPreparation.Column> definitions,List<PlsSem.Block> blocks,List<PlsSem.Edge> edges,Settings previous){return new OrdinalDialog(owner,raw,preparation,definitions,blocks,edges,previous).dialog.showAndWait();}
    static Settings read(JsonElement value){if(value==null||value.isJsonNull())return null;var object=value.getAsJsonObject();var spec=object.getAsJsonObject("specification");if(!spec.get("completeCases").isJsonPrimitive()||!spec.getAsJsonPrimitive("completeCases").isBoolean())throw new IllegalArgumentException("Ordinal completeCases must be a JSON boolean.");return new Settings(OrdinalInput.names(object.get("sourceNames")),PlsModelInput.blocks(object.get("blocks")),PlsModelInput.edges(object.get("edges")),new OrdinalData.Specification(OrdinalInput.names(spec.get("columns")),OrdinalInput.levels(spec.get("orderedLevels")),spec.get("completeCases").getAsBoolean()),OrdinalInput.options(object.get("options")));}
    static Settings smoke(Window owner,DataPreparation.Raw raw,DataPreparation.Settings preparation,List<DataPreparation.Column> definitions,Settings current,java.nio.file.Path image)throws Exception{var controls=new OrdinalDialog(owner,raw,preparation,definitions,current.blocks(),current.edges(),current);controls.dialog.show();Button run=(Button)controls.dialog.getDialogPane().lookupButton(ButtonType.OK);controls.minimum.getEditor().setText("0");run.fire();if(!controls.dialog.isShowing()||controls.result!=null)throw new AssertionError("Invalid ordinal estimation controls accepted");controls.minimum.getEditor().setText(Integer.toString(current.options().minimumCategoryCount()));controls.confirmed.setSelected(false);run.fire();if(!controls.dialog.isShowing()||controls.result!=null)throw new AssertionError("Unconfirmed text category order accepted");controls.confirmed.setSelected(true);controls.error.setText("");controls.dialog.getDialogPane().applyCss();controls.dialog.getDialogPane().layout();java.nio.file.Files.deleteIfExists(image);GraphicExport.png(image,controls.dialog.getDialogPane(),1);run.fire();if(controls.dialog.getResult()==null)throw new AssertionError("Valid ordinal configuration rejected");return controls.dialog.getResult();}
}
